tax.status:
.input {$status :string}
.match $status
single {{Modalidad de declaración: {#b}individual{/b}}}
joint {{Modalidad de declaración: {#b}conjunta{/b}}}
* {{Modalidad de declaración: {#b}otra{/b}}}

export.summary:
.input {$count :integer}
.match $count
one {{{#b}{$count} sesión{/b} del {$from :date} al {$to :date}}}
* {{{#b}{$count} sesiones{/b} del {$from :date} al {$to :date}}}
